          settings: RouteSettings(name: settings.name),
        );

      case SyncingPreferencesSettings.routeName:
        return getRoute(
          shouldUseMaterialRoute: useMaterialPageRoute,
          builder: (_) => const SyncingPreferencesSettings(),
