          );
        }
        return _routeError("${settings.name} invalid args: ${args.toString()}");

      case DeleteWalletKeysPopup.routeName:
        if (args is Tuple2<String, List<String>>) {
          return FadePageRoute(
            DeleteWalletKeysPopup(walletId: args.item1, words: args.item2),
            RouteSettings(name: settings.name),
          );
        }
        return _routeError("${settings.name} invalid args: ${args.toString()}");

      case QRCodeDesktopPopupContent.routeName:
        if (args is String) {
          return FadePageRoute(
            QRCodeDesktopPopupContent(value: args),
            RouteSettings(name: settings.name),
          );
        }
        return _routeError("${settings.name} invalid args: ${args.toString()}");

      default:
        return _routeError("");
    }
  }

  static Route<T> getRoute<T>({
    bool shouldUseMaterialRoute = useMaterialPageRoute,
    required Widget Function(BuildContext) builder,
    String? title,
    RouteSettings? settings,
    bool maintainState = true,
    bool fullscreenDialog = false,
  }) {
    if (shouldUseMaterialRoute) {
      return MaterialPageRoute<T>(
        builder: builder,
        settings: settings,
        maintainState: maintainState,
        fullscreenDialog: fullscreenDialog,
      );
    } else {
      return CupertinoPageRoute<T>(
        builder: builder,
        settings: settings,
        title: title,
        maintainState: maintainState,
        fullscreenDialog: fullscreenDialog,
      );
    }
  }

  static Route<T> createSlideTransitionRoute<T>(Widget viewToInsert) {
    return PageRouteBuilder(
      pageBuilder: (context, animation, secondaryAnimation) => viewToInsert,
      transitionsBuilder: (context, animation, secondaryAnimation, child) {
        final begin = const Offset(0.0, 1.0);
        final end = Offset.zero;
        final curve = Curves.easeInOut;

        final tween = Tween(
          begin: begin,
          end: end,
        ).chain(CurveTween(curve: curve));

        return SlideTransition(position: animation.drive(tween), child: child);
      },
    );
  }

  static Route<T> _routeError<T>(String message) {
    // Replace with robust ErrorView page
    final Widget errorView = Scaffold(
      appBar: AppBar(
        backgroundColor: Colors.black,
        title: Text(l10n.routeErrorTitle),
      ),
      body: Center(child: Text('${l10n.routeErrorText}\n$message')),
    );

    return getRoute<T>(
      shouldUseMaterialRoute: useMaterialPageRoute,
      builder: (_) => errorView,
    );
  }
}

class FadePageRoute<T> extends PageRoute<T> {
  FadePageRoute(this.child, RouteSettings settings) : _settings = settings;

  final Widget child;
  final RouteSettings _settings;

  @override
  Color? get barrierColor => null;

  @override
  String? get barrierLabel => null;

  @override
  Widget buildPage(
    BuildContext context,
    Animation<double> animation,
    Animation<double> secondaryAnimation,
  ) {
    return FadeTransition(opacity: animation, child: child);
  }

  @override
  bool get maintainState => true;

  @override
  Duration get transitionDuration => const Duration(milliseconds: 100);

  @override
  RouteSettings get settings => _settings;
}
